# WorldQuant 101 核心算子实现
def ts_rank(x, d):
    return x.rolling(d).apply(lambda s: s.rank().iloc[-1] / d)
def ts_delta(x, d):
    return x - x.shift(d)
def ts_mean(x, d):
    return x.rolling(d).mean()
def ts_std(x, d):
    return x.rolling(d).std()
def ts_corr(x, y, d):
    return x.rolling(d).corr(y)
def signedpower(x, a):
    return np.sign(x) * np.abs(x) ** a
def decay_linear(x, d):
    w = np.arange(1, d+1) / np.arange(1, d+1).sum()
    return x.rolling(d).apply(lambda s: (s * w).sum())
