# 经典alpha模式的Python实现
class AlphaPatterns:
    @staticmethod
    def mean_reversion(data, d=10):
        ret = data['close'].pct_change(d)
        return -ret.rank(pct=True)  # 模式1: 均值回复
    @staticmethod
    def low_volatility(data, d=20):
        ret = data['close'].pct_change(1)
        std = ret.rolling(d).std()
        return -std.rank(pct=True)  # 模式4: 低波动
    @staticmethod
    def pv_divergence(data, d=20):
        ret = data['close'].pct_change(1)
        vol = data['volume']
        correl = ret.rolling(d).corr(vol)
        return -correl.rank(pct=True)  # 模式3: 价量背离

# IC衰减诊断
def diagnose_ic_decay(ic_series, train_test_split_idx):
    train_ic = ic_series[:train_test_split_idx].mean()
    test_ic = ic_series[train_test_split_idx:].mean()
    decay_ratio = (train_ic - test_ic) / train_ic
    if decay_ratio > 0.5:
        return 'OVERFIT'  # 大概率过拟合
    elif decay_ratio > 0.3:
        return 'MODERATE_DECAY'  # 需关注
    else:
        return 'HEALTHY'  # 正常衰减范围

